{
  "name": "可编程逻辑控制器（PLC）",
  "name_en": "Programmable Logic Controller (PLC)",
  "manufacturer": "",
  "description": "用于实验室自动化、联锁和设备集成的可编程逻辑控制器，可通过 EtherNet/IP 读取和写入标签、同步控制器时钟、查询程序与模块信息，并发送自定义 CIP 消息。",
  "description_en": "A programmable logic controller used for laboratory automation, interlocks, and equipment integration. It is accessed over EtherNet/IP to read and write tags, synchronize the controller clock, query program and module information, and send custom CIP messages.",
  "actions": [
    {
      "action_name": "auto-ConnectionSize",
      "description": "获取/设置连接大小",
      "description_en": "get/set connection size"
    },
    {
      "action_name": "auto-Read",
      "description": "读取PLC标签值或数组",
      "description_en": "Read a PLC tag value or array."
    },
    {
      "action_name": "auto-Write",
      "description": "写入PLC标签值或数组",
      "description_en": "Write a PLC tag value or array."
    },
    {
      "action_name": "auto-GetPLCTime",
      "description": "读取PLC控制器时钟",
      "description_en": "Read the PLC controller clock time."
    },
    {
      "action_name": "auto-SetPLCTime",
      "description": "设置PLC控制器时钟",
      "description_en": "Set the PLC controller clock time."
    },
    {
      "action_name": "auto-GetTagList",
      "description": "获取PLC标签列表",
      "description_en": "Retrieve the PLC tag list."
    },
    {
      "action_name": "auto-GetProgramTagList",
      "description": "获取指定程序的标签列表",
      "description_en": "Retrieve the tag list for a specified program."
    },
    {
      "action_name": "auto-GetProgramsList",
      "description": "获取PLC程序名称列表",
      "description_en": "Retrieve the PLC program name list."
    },
    {
      "action_name": "auto-Discover",
      "description": "发现网络中的EtherNet/IP设备",
      "description_en": "Discover EtherNet/IP devices on the network."
    },
    {
      "action_name": "auto-GetModuleProperties",
      "description": "获取指定槽位模块属性",
      "description_en": "Get properties of the module in a specified slot."
    },
    {
      "action_name": "auto-GetDeviceProperties",
      "description": "获取目标设备属性",
      "description_en": "Get properties of the target device."
    },
    {
      "action_name": "auto-Message",
      "description": "发送自定义CIP消息",
      "description_en": "Send a custom CIP message."
    },
    {
      "action_name": "auto-ReceiveMessage",
      "description": "监听并接收EtherNet/IP消息",
      "description_en": "Listen for and receive EtherNet/IP messages."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭与PLC的连接",
      "description_en": "Close the connection to the PLC."
    }
  ],
  "tag_hints": [
    "PLC automation",
    "EtherNet/IP",
    "CIP messaging",
    "tag read/write",
    "controller clock sync",
    "module properties",
    "industrial control"
  ]
}

